import { DurableObject } from "cloudflare:workers";
import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import { Type } from "@earendil-works/pi-ai";
import type { EntryRecord, Wake } from "@earendil-works/pi-durable";
import { createRegistry, defineExtension, defineTool, GenerationTask, Harness, hook } from "@earendil-works/pi-durable";
import { openDurableObjectSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/cloudflare";
import articleHtml from "../fixtures/article.html";
import { agentModels, GLM_5_3_FLASH_ID } from "./model-provider.ts";
import { RecipesDoc, submitRecipeTool } from "./recipe-tool.ts";

const context = BACKGROUND_CONTEXT;

const INSTRUCTIONS = `You author extraction recipes for one article at a time.

Call fetch_article to get the article's html. Write the whole recipe module on your first try: a JavaScript ES module exporting container (a selector string), ignores (a list of { selector, reason }) and extract($, toMarkdown). Call submit_recipe with it, read the result, fix whatever it names, and submit again. Repeat until it says ACCEPTED, then reply with one fenced json block: {"kind": "script", "source": "<the accepted module>"}. Keep the module short.`;

export type CrashMode = "none" | "tool" | "turn";

export interface RunResult {
  conversationId: string;
  status: string;
  submissions: number;
  entries: { kind: string; summary: string }[];
  usage: unknown;
  log: string[];
}

const summarize = (entry: EntryRecord) => {
  const message = entry.model?.[0] as
    | { role: string; content: unknown; toolName?: string; stopReason?: string }
    | undefined;

  if (message == null) {
    return "";
  }

  const parts = Array.isArray(message.content) ? message.content : [{ type: "text", text: String(message.content) }];
  const text = parts
    .map((part: { type: string; text?: string; name?: string; arguments?: unknown }) =>
      part.type === "toolCall" ? `toolCall:${part.name}` : part.type === "text" ? (part.text ?? "") : part.type,
    )
    .join(" | ");

  return `${message.role}${message.toolName == null ? "" : `(${message.toolName})`}: ${text.replace(/\s+/g, " ").slice(0, 160)}`;
};

export class AuthorAgent extends DurableObject<Env> {
  #harness!: Harness;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);

    this.#log(`constructor (instance start)`);

    void ctx.blockConcurrencyWhile(async () => {
      const fallback = Date.now() + 60_000;
      const current = await ctx.storage.getAlarm();

      if (current === null || current > fallback) {
        await ctx.storage.setAlarm(fallback);
      }

      const storage = await openDurableObjectSqliteStorage(ctx.storage);
      const onWake = (wake: Wake) => void this.#arm(wake).catch(() => ctx.abort("Alarm write failed"));

      this.#harness = await Harness.open(
        storage,
        {
          models: agentModels(),
          registry: this.#registry(),
          onWake,
          onReport: (error, info) => this.#log(`report ${info.type}: ${String(error)}`),
        },
        context,
      );

      await this.#arm(this.#harness.wake());
      const inspection = await this.#harness.inspect(context);
      this.#log(`opened; live tasks: ${JSON.stringify(inspection.tasks.map((task) => `${task.record.kind}:${task.record.state.status}`))}`);
      this.#harness.resume();
    });
  }

  override async alarm(): Promise<void> {
    this.#log(`alarm fired`);
    await this.#arm({ ...this.#harness.wake(), active: true });
    this.#harness.resume();
  }

  async run(message: string, requestId: string, crash: CrashMode): Promise<RunResult> {
    this.ctx.storage.kv.put("crash", crash);
    await this.#arm({ ...this.#harness.wake(), active: true });

    const root = await this.#harness.root(context, {
      agent: { model: { provider: "cloudflare-ai-gateway", modelId: GLM_5_3_FLASH_ID }, thinkingLevel: "off", instructions: INSTRUCTIONS },
    });
    const submission = await root.submit({ type: "input", content: message, requestId }, context);
    this.#log(`submitted ${requestId} → submission ${submission.id}`);
    const settled = await submission.wait(context);
    this.#log(`settled ${requestId}: ${settled.status}`);

    return this.#result(settled.status);
  }

  async state(): Promise<RunResult> {
    return this.#result("inspect");
  }

  async #result(status: string): Promise<RunResult> {
    const root = await this.#harness.root(context);
    const page = await root.entries({ order: "ascending" }, 200, undefined, context);
    const recipes = await this.#harness.snapshot(RecipesDoc, root.id, context);

    return {
      conversationId: String(root.id),
      status,
      submissions: recipes?.submissions.length ?? 0,
      entries: page.items.map((entry) => ({ kind: entry.kind, summary: summarize(entry) })),
      usage: await this.#harness.usage(context),
      log: (this.ctx.storage.kv.get("log") as string[] | undefined) ?? [],
    };
  }

  #registry() {
    const registry = createRegistry();

    const fetchArticle = defineTool({
      name: "fetch_article",
      description: "Return the article page's html.",
      parameters: Type.Object({}),
      execute: async () => {
        this.#log(`tool fetch_article executes`);
        return { output: [{ type: "text", text: articleHtml }] };
      },
    });

    const submitRecipe = submitRecipeTool(async (api) => {
      this.#log(`tool submit_recipe executes (task ${api.taskId})`);

      if (this.ctx.storage.kv.get("crash") === "tool" && this.ctx.storage.kv.get("crashed") !== true) {
        await this.#markCrashed();
        this.#log(`CRASH: ctx.abort() inside submit_recipe`);
        this.ctx.abort("spike: crash inside a tool call");
      }
    });

    const logging = hook(GenerationTask, {
      beforeRequest: (request) => {
        const requests = ((this.ctx.storage.kv.get("requests") as number | undefined) ?? 0) + 1;
        this.ctx.storage.kv.put("requests", requests);
        this.#log(`model request #${requests} (${request.messages.length} messages)`);

        if (requests === 2 && this.ctx.storage.kv.get("crash") === "turn" && this.ctx.storage.kv.get("crashed") !== true) {
          this.#log(`CRASH: ctx.abort() scheduled 2.5s into model request #2`);
          void this.#markCrashed().then(() => setTimeout(() => this.ctx.abort("spike: crash mid model turn"), 2_500));
        }

        return undefined;
      },
      afterResponse: (answer) => {
        this.#log(`model response: stop=${answer.stopReason} content=${answer.content.map((part) => part.type).join(",")}`);
      },
    });

    registry.install(defineExtension({ name: "author", tools: [fetchArticle, submitRecipe], hooks: [logging] }));
    return registry;
  }

  async #arm(wake: Wake): Promise<void> {
    const heartbeat = wake.active ? Date.now() + 60_000 : undefined;
    const at = heartbeat === undefined || wake.at === undefined ? (heartbeat ?? wake.at) : Math.min(heartbeat, wake.at);

    if (at === undefined) {
      await this.ctx.storage.deleteAlarm();
      return;
    }

    await this.ctx.storage.setAlarm(at);
  }

  // ctx.abort() discards writes not yet flushed, so the flag is flushed first or the next instance crashes again.
  async #markCrashed() {
    this.ctx.storage.kv.put("crashed", true);
    await this.ctx.storage.sync();
  }

  // Kept outside pi's transactions on purpose: the log must survive the crash it records.
  #log(line: string) {
    const stamped = `${new Date().toISOString()} ${line}`;
    console.log(`SPIKE ${stamped}`);
    const log = (this.ctx.storage.kv.get("log") as string[] | undefined) ?? [];
    log.push(stamped);
    this.ctx.storage.kv.put("log", log);
  }
}
