import { Type } from "@earendil-works/pi-ai";
import type { ToolExecutionApi } from "@earendil-works/pi-durable";
import { defineTool } from "@earendil-works/pi-durable";
import pageA from "../fixtures/page-a.html";
import pageB from "../fixtures/page-b.html";

export const PAGE_A = "https://fieldnotes.example/posts/build-got-slower";
export const PAGE_B = "https://fieldnotes.example/posts/flaky-test-clock";

export const pages: Record<string, string> = { [PAGE_A]: pageA, [PAGE_B]: pageB };

// Crude stand-in for running a recipe: every class and tag of the container selector must occur in the page.
export const crudeCheck = (script: string, html: string): string | undefined => {
  const container = /container\s*[:=]\s*["'`]([^"'`]+)["'`]/.exec(script)?.[1];

  if (container == null) {
    return "the script exports no container selector";
  }

  const missing = container
    .split(/[\s>+~,]+/)
    .filter((part) => part.length > 0)
    .flatMap((part) => {
      const [tag, ...classes] = part.split(".");
      const tagMissing = tag !== "" && !/^[*#[]/.test(tag) && !html.includes(`<${tag}`) ? [`<${tag}>`] : [];
      const classesMissing = classes.filter((name) => !new RegExp(`class="[^"]*\\b${name}\\b`).test(html)).map((name) => `.${name}`);
      return [...tagMissing, ...classesMissing];
    });

  return missing.length === 0 ? undefined : `container selector "${container}" matches nothing: ${missing.join(", ")} not on the page`;
};

export const fetchPageTool = (beforeExecute: (api: ToolExecutionApi) => Promise<void>) =>
  defineTool({
    name: "fetch_page",
    description: "Return a page's html by url.",
    parameters: Type.Object({ url: Type.String() }),
    replay: "safe",
    execute: async (args, api) => {
      await beforeExecute(api);
      const html = pages[args.url];

      if (html == null) {
        throw new Error(`no page at ${args.url}`);
      }

      return { output: [{ type: "text", text: html }] };
    },
  });

export const submitRecipeTool = (beforeExecute: (api: ToolExecutionApi) => Promise<void>) =>
  defineTool({
    name: "submit_recipe",
    description: "Submit a complete recipe module's source for one page url. Returns ACCEPTED or REJECTED with the reason.",
    parameters: Type.Object({ url: Type.String(), script: Type.String({ description: "The full recipe module source" }) }),
    replay: "safe",
    execute: async (args, api) => {
      await beforeExecute(api);
      const html = pages[args.url];
      const problem = html == null ? `no page at ${args.url}` : crudeCheck(args.script, html);
      const text = problem == null ? "ACCEPTED: reply with the settled script." : `REJECTED: ${problem}`;

      return { output: [{ type: "text", text }] };
    },
  });

import { defineDoc, defineTask } from "@earendil-works/pi-durable";
import type { ConversationId, EntryRecord } from "@earendil-works/pi-durable";

export type ReviseMode = "fork" | "continue";

export interface ReviseInput {
  url: string;
  report: string;
  script: string;
  mode: ReviseMode;
  [key: string]: string;
}

export interface ReviseResult {
  childId: number;
  forkedAt: number | null;
  submissionStatus: string;
  answer: string;
  [key: string]: string | number | null;
}

type ReviseState = { phase: "start" } | { phase: "run"; childId: number; forkedAt: number | null };

// Kept on the author's conversation: requestId → revise task, and every revisor child made so far.
export const RevisionsDoc = defineDoc<{ byRequest: Record<string, number>; children: number[] }>({
  kind: "spike.revisions",
  version: 1,
  scope: "conversation",
  history: "latest",
  fork: "initial",
  initial: () => ({ byRequest: {}, children: [] }),
  checkpointWhen: () => false,
});

export const revisionPrompt = (input: ReviseInput) => `REVISION REQUEST. The recipe you settled earlier in this conversation now fails on another page of the same site: ${input.url}

Failure report: ${input.report}

The saved script:
\`\`\`js
${input.script}
\`\`\`

Before anything else, on its own line, write "NONCE: " followed by the nonce from the very first message of this conversation, or "NONCE: none" if you cannot see one. Then fetch the new page with fetch_page, fix the script so it works on both pages, submit it with submit_recipe for the new url, and once ACCEPTED reply with one fenced json block: {"kind": "script", "source": "<the accepted module>"}.`;

const lastText = (entries: readonly EntryRecord[]) => {
  const assistant = entries.findLast((entry) => entry.kind === "pi.assistant");
  const message = assistant?.model?.[0] as { content: { type: string; text?: string }[] } | undefined;

  return message?.content.map((part) => part.text ?? "").join("") ?? "";
};

export const ReviseTask = defineTask<ReviseInput, ReviseState, ReviseResult>({
  name: "spike.revise",
  version: 1,
  initial: () => ({ phase: "start" }),
  phases: {
    // Creates (or, in "continue" mode, reuses) the revisor child in one commit with the next checkpoint, so a rerun finds it.
    start: async (task, runtime, context) => {
      const authorId = runtime.conversationId;

      await runtime.commit(async (tx) => {
        const revisions = await tx.doc(RevisionsDoc, authorId);
        const previous = revisions.children.at(-1);

        if (task.input.mode === "continue" && previous != null) {
          return { status: "running", checkpoint: { phase: "run", childId: previous, forkedAt: null } };
        }

        const last = (await tx.scanEntries({ conversationId: authorId, order: "descending" }, 1)).items[0];
        const child = await tx.forkConversation(authorId, last.id, { ownership: { kind: "task", taskId: runtime.taskId } });
        revisions.children.push(Number(child.id));

        return { status: "running", checkpoint: { phase: "run", childId: Number(child.id), forkedAt: Number(last.id) } };
      }, context);
    },
    run: async (task, runtime, context) => {
      const childId = task.state.checkpoint.childId as unknown as ConversationId;
      const child = await runtime.conversation(childId, context);

      if (child == null) {
        throw new Error(`revisor child ${childId} is gone`);
      }

      // Keyed by the task, so a rerun of this phase after a crash reattaches to the same submission.
      const submission = await child.submit({ type: "input", content: revisionPrompt(task.input), requestId: `revise:${task.id}` }, context);
      const settled = await submission.wait(context);
      const page = await child.entries({ order: "ascending" }, 500, undefined, context);

      await runtime.commit(
        () => ({
          status: "terminal",
          outcome: {
            status: "completed",
            result: {
              childId: task.state.checkpoint.childId,
              forkedAt: task.state.checkpoint.forkedAt,
              submissionStatus: settled.status,
              answer: lastText(page.items),
            },
          },
        }),
        context,
      );
    },
  },
  abort: async (_task, runtime, context) => {
    await runtime.commit(() => ({ status: "terminal", outcome: { status: "aborted", reason: "spike abort" } }) as never, context);
  },
});

import { DurableObject } from "cloudflare:workers";
import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import type { ConversationId, EntryRecord, UsageState, Wake } from "@earendil-works/pi-durable";
import { createRegistry, defineExtension, GenerationTask, Harness, hook, UsageDoc } from "@earendil-works/pi-durable";
import { openDurableObjectSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/cloudflare";
import { agentModels, GLM_5_3_FLASH_ID } from "./model-provider.ts";
import type { ReviseInput, ReviseMode, ReviseResult } from "./revise-task.ts";
import { RevisionsDoc, ReviseTask, revisionPrompt } from "./revise-task.ts";
import { fetchPageTool, submitRecipeTool } from "./tools.ts";

const context = BACKGROUND_CONTEXT;

const INSTRUCTIONS = `You author extraction recipes for article pages.

Call fetch_page with the url to get its html. Write the whole recipe module on your first try: a JavaScript ES module exporting container (a selector string), ignores (a list of { selector, reason }) and extract($, toMarkdown). Call submit_recipe with the url and the module, read the result, fix whatever it names, and submit again. Repeat until it says ACCEPTED, then reply with one fenced json block: {"kind": "script", "source": "<the accepted module>"}. Keep the module short.`;

export type CrashMode = "none" | "revise-turn";

export interface ConversationReport {
  id: number;
  parent?: { conversationId: number; at: number };
  owner?: unknown;
  entries: { id: number; kind: string; summary: string }[];
  usage: UsageState | undefined;
}

const summarize = (entry: EntryRecord) => {
  const message = entry.model?.[0] as { role: string; content: unknown; toolName?: string; stopReason?: string } | undefined;

  if (message == null) {
    return "";
  }

  const parts = Array.isArray(message.content) ? message.content : [{ type: "text", text: String(message.content) }];
  const text = parts
    .map((part: { type: string; text?: string; name?: string }) =>
      part.type === "toolCall" ? `toolCall:${part.name}` : part.type === "text" ? (part.text ?? "") : part.type,
    )
    .join(" | ");
  const stop = message.stopReason == null || message.stopReason === "stop" || message.stopReason === "toolUse" ? "" : ` [${message.stopReason}]`;

  return `${message.role}${message.toolName == null ? "" : `(${message.toolName})`}${stop}: ${text.replace(/\s+/g, " ").slice(0, 150)}`;
};

export class ItemAgent extends DurableObject<Env> {
  #harness!: Harness;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);

    this.#log(`constructor (instance start)`);

    void ctx.blockConcurrencyWhile(async () => {
      const fallback = Date.now() + 60_000;
      const current = await ctx.storage.getAlarm();

      if (current === null || current > fallback) {
        await ctx.storage.setAlarm(fallback);
      }

      const storage = await openDurableObjectSqliteStorage(ctx.storage);
      const onWake = (wake: Wake) => void this.#arm(wake).catch(() => ctx.abort("Alarm write failed"));

      this.#harness = await Harness.open(
        storage,
        {
          models: agentModels(),
          registry: this.#registry(),
          onWake,
          onReport: (error, info) => this.#log(`report ${info.type}: ${String(error)}`),
        },
        context,
      );

      await this.#arm(this.#harness.wake());
      const inspection = await this.#harness.inspect(context);
      this.#log(`opened; live tasks: ${JSON.stringify(inspection.tasks.map((task) => `${task.record.id}:${task.record.kind}:${task.record.state.status}`))}`);
      this.#harness.resume();
    });
  }

  override async alarm(): Promise<void> {
    this.#log(`alarm fired`);
    await this.#arm({ ...this.#harness.wake(), active: true });
    this.#harness.resume();
  }

  async author(message: string, requestId: string) {
    await this.#arm({ ...this.#harness.wake(), active: true });

    const root = await this.#harness.root(context, {
      agent: { model: { provider: "cloudflare-ai-gateway", modelId: GLM_5_3_FLASH_ID }, thinkingLevel: "off", instructions: INSTRUCTIONS },
    });
    const submission = await root.submit({ type: "input", content: message, requestId }, context);
    this.#log(`author: submitted ${requestId} → submission ${submission.id}`);
    const settled = await submission.wait(context);
    this.#log(`author: settled ${requestId}: ${settled.status}`);

    const page = await root.entries({ order: "descending" }, 1, undefined, context);
    const text = summarizeFull(page.items[0]);
    const source = /"source"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text)?.[1];
    const script = source == null ? undefined : (JSON.parse(`"${source}"`) as string);

    if (script != null) {
      this.ctx.storage.kv.put("savedScript", script);
    }

    return { status: settled.status, script };
  }

  savedScript() {
    return this.ctx.storage.kv.get("savedScript") as string | undefined;
  }

  // The revisor runs as a task the author's conversation owns; its conversation is a fork owned by that task.
  async revise(input: ReviseInput, requestId: string, crash: CrashMode): Promise<ReviseResult & { taskId: number; status: string }> {
    this.ctx.storage.kv.put("crash", crash);
    await this.#arm({ ...this.#harness.wake(), active: true });

    const root = await this.#harness.root(context);
    const taskId = await root.commit(async (tx) => {
      const revisions = await tx.doc(RevisionsDoc, root.id);
      const existing = revisions.byRequest[requestId];

      if (existing != null) {
        return existing;
      }

      const created = await tx.createTask(ReviseTask, input, { ownership: { kind: "conversation" } });
      revisions.byRequest[requestId] = Number(created);
      return Number(created);
    }, context);
    this.#log(`revise: ${requestId} → task ${taskId}`);

    const settled = await this.#harness.waitForTask(taskId as never, context);
    const outcome = settled.state.outcome as { status: string; result?: ReviseResult; error?: unknown };
    this.#log(`revise: task ${taskId} settled ${outcome.status}`);

    return { taskId, status: outcome.status, ...(outcome.result ?? ({ error: JSON.stringify(outcome.error) } as never)) };
  }

  // A conversation with no shared history, given the same revision prompt, for the token comparison.
  async reviseSeparately(input: ReviseInput, requestId: string) {
    await this.#arm({ ...this.#harness.wake(), active: true });

    const existing = this.ctx.storage.kv.get("separateId") as number | undefined;
    const conversation =
      existing == null
        ? await this.#harness.createConversation(
            {
              ownership: { kind: "ownerless" },
              agent: { model: { provider: "cloudflare-ai-gateway", modelId: GLM_5_3_FLASH_ID }, thinkingLevel: "off", instructions: INSTRUCTIONS },
            },
            context,
          )
        : (await this.#harness.conversation(existing as unknown as ConversationId, context))!;
    this.ctx.storage.kv.put("separateId", Number(conversation.id));

    const submission = await conversation.submit({ type: "input", content: revisionPrompt(input), requestId }, context);
    const settled = await submission.wait(context);

    return { conversationId: Number(conversation.id), status: settled.status };
  }

  async state(ids: number[]) {
    const reports: ConversationReport[] = [];
    const root = await this.#harness.root(context);
    const revisions = await this.#harness.snapshot(RevisionsDoc, root.id, context);
    const separate = this.ctx.storage.kv.get("separateId") as number | undefined;
    const all = [...new Set([Number(root.id), ...(revisions?.children ?? []), ...(separate == null ? [] : [separate]), ...ids])];

    for (const id of all) {
      const conversation = await this.#harness.conversation(id as unknown as ConversationId, context);

      if (conversation == null) {
        continue;
      }

      const record = await this.#harness.inspectConversation?.(conversation.id, context).catch(() => undefined);
      const page = await conversation.entries({ order: "ascending" }, 500, undefined, context);

      reports.push({
        id,
        owner: record,
        entries: page.items.map((entry) => ({ id: Number(entry.id), kind: entry.kind, summary: summarize(entry) })),
        usage: await this.#harness.snapshot(UsageDoc, conversation.id, context),
      });
    }

    return {
      revisions,
      conversations: reports,
      sessionUsage: await this.#harness.usage(context),
      requests: (this.ctx.storage.kv.get("requests") as unknown[] | undefined) ?? [],
      log: (this.ctx.storage.kv.get("log") as string[] | undefined) ?? [],
    };
  }

  #registry() {
    const registry = createRegistry();
    const noop = async () => {};

    const logging = hook(GenerationTask, {
      beforeRequest: (request, api) => {
        const requests = (this.ctx.storage.kv.get("requests") as unknown[] | undefined) ?? [];
        const conversationId = Number(api.conversationId);
        const inConversation = requests.filter((item) => (item as { conversationId: number }).conversationId === conversationId).length + 1;
        const firstUser = request.messages.find((message) => message.role === "user");
        const firstText = typeof firstUser?.content === "string" ? firstUser.content : JSON.stringify(firstUser?.content ?? "");

        requests.push({
          n: requests.length + 1,
          conversationId,
          inConversation,
          messages: request.messages.length,
          roles: request.messages.map((message) => message.role[0]).join(""),
          firstUser: firstText.slice(0, 90),
        });
        this.ctx.storage.kv.put("requests", requests);
        this.#log(`model request #${requests.length} conv ${conversationId} (#${inConversation} there, ${request.messages.length} messages)`);

        const isChild = conversationId !== 1;

        if (isChild && inConversation === 2 && this.ctx.storage.kv.get("crash") === "revise-turn" && this.ctx.storage.kv.get("crashed") !== true) {
          this.#log(`CRASH: ctx.abort() scheduled 2.5s into the revisor's request #2`);
          void this.#markCrashed().then(() => setTimeout(() => this.ctx.abort("spike: crash mid revision"), 2_500));
        }

        return undefined;
      },
      afterResponse: (answer, api) => {
        this.#log(`model response conv ${Number(api.conversationId)}: stop=${answer.stopReason} content=${answer.content.map((part) => part.type).join(",")}`);
      },
    });

    registry.install(
      defineExtension({
        name: "author",
        tools: [fetchPageTool(noop), submitRecipeTool(async (api) => this.#log(`tool submit_recipe executes (task ${api.taskId}, conv ${api.conversationId})`))],
        hooks: [logging],
        tasks: [ReviseTask],
      }),
    );
    return registry;
  }

  async #arm(wake: Wake): Promise<void> {
    const heartbeat = wake.active ? Date.now() + 60_000 : undefined;
    const at = heartbeat === undefined || wake.at === undefined ? (heartbeat ?? wake.at) : Math.min(heartbeat, wake.at);

    if (at === undefined) {
      await this.ctx.storage.deleteAlarm();
      return;
    }

    await this.ctx.storage.setAlarm(at);
  }

  // ctx.abort() discards writes not yet flushed, so the flag is flushed first or the next instance crashes again.
  async #markCrashed() {
    this.ctx.storage.kv.put("crashed", true);
    await this.ctx.storage.sync();
  }

  // Kept outside pi's transactions on purpose: the log must survive the crash it records.
  #log(line: string) {
    const stamped = `${new Date().toISOString()} ${line}`;
    console.log(`SPIKE ${stamped}`);
    const log = (this.ctx.storage.kv.get("log") as string[] | undefined) ?? [];
    log.push(stamped);
    this.ctx.storage.kv.put("log", log);
  }
}

const summarizeFull = (entry: EntryRecord | undefined) => {
  const message = entry?.model?.[0] as { content: { type: string; text?: string }[] } | undefined;
  return message?.content.map((part) => part.text ?? "").join("") ?? "";
};

export type { ReviseMode };

import { Data, Effect, Schedule } from "effect";
import type { CrashMode } from "./agent.ts";
import type { ReviseMode } from "./revise-task.ts";
import { crudeCheck, PAGE_A, PAGE_B, pages } from "./tools.ts";

export { ItemAgent } from "./agent.ts";

class AgentCallError extends Data.TaggedError("AgentCallError")<{ message: string }> {}

const AUTHOR_MESSAGE = `Write the extraction recipe for ${PAGE_A}. (Nonce for this item: KIWI-7731-TANGERINE. Do not repeat it unless asked.)`;

// A stand-in for a Workflow step's call: retried on failure, every attempt with the same requestId.
const call = <A>(label: string, attempt: () => Promise<A>, retries: number) =>
  Effect.gen(function* () {
    const counter = { n: 0 };

    const result = yield* Effect.tryPromise({
      try: () => {
        counter.n += 1;
        console.log(`SPIKE caller attempt ${counter.n} for ${label}`);
        return attempt();
      },
      catch: (cause) => new AgentCallError({ message: String(cause) }),
    }).pipe(
      Effect.tapError((error) => Effect.logWarning(`caller attempt failed: ${error.message}`)),
      Effect.retry({ schedule: Schedule.spaced("2 seconds"), times: retries }),
    );

    return { attempts: counter.n, result };
  });

// The recipe step: run the saved script's check against page B, and hand the report to the revisor when it fails.
const failingInput = async (env: Env, id: string, mode: ReviseMode) => {
  const script = await env.ITEM.getByName(id).savedScript();

  if (script == null) {
    throw new Error("no saved script; run /author first");
  }

  const report = crudeCheck(script, pages[PAGE_B]);

  if (report == null) {
    throw new Error("the saved script passes on page B; nothing to revise");
  }

  return { url: PAGE_B, report, script, mode };
};

const respond = <A>(program: Effect.Effect<A, AgentCallError>) =>
  Effect.runPromise(
    program.pipe(
      Effect.map((result) => Response.json(result)),
      Effect.catchTag("AgentCallError", (error) => Effect.succeed(Response.json({ error: error.message }, { status: 502 }))),
    ),
  );

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const id = url.searchParams.get("id") ?? "default";
    const body = request.method === "POST" ? ((await request.json()) as Record<string, unknown>) : {};
    const stub = env.ITEM.getByName(id);
    const retries = (body.retries as number | undefined) ?? 4;
    const requestId = body.requestId as string;

    if (url.pathname === "/state") {
      const extra = (url.searchParams.get("ids") ?? "").split(",").filter(Boolean).map(Number);
      return Response.json(await stub.state(extra));
    }

    if (url.pathname === "/author") {
      return respond(call(`author ${id}/${requestId}`, () => stub.author(AUTHOR_MESSAGE, requestId), retries));
    }

    if (url.pathname === "/revise") {
      const input = await failingInput(env, id, (body.mode as ReviseMode | undefined) ?? "fork");
      return respond(call(`revise ${id}/${requestId}`, () => stub.revise(input, requestId, (body.crash as CrashMode | undefined) ?? "none"), retries));
    }

    if (url.pathname === "/revise-separately") {
      const input = await failingInput(env, id, "fork");
      return respond(call(`revise-separately ${id}/${requestId}`, () => stub.reviseSeparately(input, requestId), retries));
    }

    return new Response("not found", { status: 404 });
  },
} satisfies ExportedHandler<Env>;

